// Generated by the private Rust CLI from the shared original-error provenance classifier.
const importerUrl = new URL("../client.js", import.meta.url).href;
const loaderSpecifier = "../generated/native/binding.cjs";
const loaderUrl = new URL(loaderSpecifier, importerUrl).href;
const companionStem = "@acyclic-labs/actors-";
export async function isExpectedNativeAbsence(error: unknown): Promise<boolean> {
  if (isMissingGeneratedLoader(error)) return true;
  if (!errorMessage(error).startsWith("Cannot find native binding. ")) return false;
  const { createRequire } = await import("node:module");
  const requireNative = createRequire(importerUrl);
  if (error instanceof AggregateError) {
    return error.errors.length > 0 && error.errors.every(cause =>
      isMissingNativeCandidate(cause, specifier => requireNative.resolve(specifier), true));
  }
  let cause = errorCause(error);
  let foundCause = false;
  while (cause !== undefined && cause !== null) {
    foundCause = true;
    if (!isMissingNativeCandidate(cause, specifier => requireNative.resolve(specifier))) return false;
    cause = errorCause(cause);
  }
  return foundCause;
}

function isMissingGeneratedLoader(error: unknown): boolean {
  if (typeof error !== "object" || error === null) return false;
  const code = "code" in error && typeof error.code === "string" ? error.code : undefined;
  if (code !== "ERR_MODULE_NOT_FOUND" && code !== "MODULE_NOT_FOUND") return false;
  const message = errorMessage(error);
  const firstLine = message.split(/\r?\n/, 1)[0] ?? message;
  const requested = firstLine.match(/^(?:ResolveMessage:\s*)?Cannot find module ['"]([^'"]+)['"]/i)?.[1];
  if (requested === undefined) return false;
  if (requested === loaderSpecifier) {
    const importer = moduleImporter(firstLine);
    if (importer === undefined) return false;
    const expected = normalizeModulePath(importerUrl);
    const actual = normalizeModulePath(importer);
    // Bun executes the maintained .ts source directly. Permit that exact
    // importer only while this classifier itself is running from .ts source.
    return actual === expected || (import.meta.url.endsWith(".ts") && actual === normalizeModulePath(importerUrl.replace(/\.js$/, ".ts")));
  }
  // Only the package's own generated loader is optional. Matching a path
  // suffix would incorrectly turn a broken transitive dependency into a
  // silent WASM fallback.
  return isOwnGeneratedLoader(requested);
}

function isMissingNativeCandidate(error: unknown, resolve: (specifier: string) => string, original = false): boolean {
  if (typeof error !== "object" || error === null) return false;
  const code = "code" in error && typeof error.code === "string" ? error.code : undefined;
  const message = errorMessage(error);
  const firstLine = message.split(/\r?\n/, 1)[0] ?? message;
  if (/^Unsupported (?:OS|architecture)\b/.test(firstLine)) {
    if (!original || !("stack" in error) || typeof error.stack !== "string") return false;
    const frame = error.stack.split(/\r?\n/)[1] ?? "";
    const path = frame.match(/\((.+):\d+:\d+\)$/)?.[1]
      ?? frame.match(/^\s*at (.+):\d+:\d+$/)?.[1];
    return path !== undefined && isOwnGeneratedLoader(path);
  }
  if (code !== undefined && code !== "ERR_MODULE_NOT_FOUND" && code !== "MODULE_NOT_FOUND") return false;
  if (!hasGeneratedLoaderRequireStack(message)) return false;
  const requested = firstLine.match(/^Cannot find (?:module|package) ['"]([^'"]+)['"]/i)?.[1];
  if (requested !== undefined && isCompanion(requested)) {
    try { resolve(`${requested}/package.json`); return false; }
    catch (error) {
      if (typeof error !== "object" || error === null || !("code" in error) || error.code !== "MODULE_NOT_FOUND") throw error;
    }
  }
  return requested !== undefined
    && (/^\.\/index\.[^/]+\.(?:node|cjs)$/.test(requested) || isCompanion(requested, true));
}

function hasGeneratedLoaderRequireStack(message: string): boolean {
  const lines = message.split(/\r?\n/);
  const marker = lines.findIndex(line => line.trim() === "Require stack:");
  if (marker >= 0) {
    const firstFrame = lines[marker + 1]?.trim().replace(/^-\s*/, "");
    return firstFrame !== undefined && isOwnGeneratedLoader(firstFrame);
  }
  // Bun reports the same provenance inline instead of emitting Node's
  // `Require stack` block. Keep the source check equally narrow so a missing
  // dependency from inside an optional companion still propagates.
  const source = moduleImporter(lines[0] ?? "");
  return source !== undefined && isOwnGeneratedLoader(source);
}

function moduleImporter(message: string): string | undefined {
  const match = message.match(/\s(?:imported )?from (?:['"]([^'"]+)['"]|(.+))$/i);
  return match?.[1] ?? match?.[2];
}

function isOwnGeneratedLoader(path: string): boolean {
  return normalizeModulePath(path) === normalizeModulePath(loaderUrl);
}

function errorMessage(error: unknown): string {
  return typeof error === "object" && error !== null && "message" in error && typeof error.message === "string" ? error.message : String(error);
}

function errorCause(error: unknown): unknown {
  return typeof error === "object" && error !== null && "cause" in error
    ? (error as { readonly cause?: unknown }).cause
    : undefined;
}

function normalizeModulePath(path: string): string {
  let value = path;
  if (value.startsWith("file:")) {
    try { value = new URL(value).pathname; } catch { return ""; }
  }
  try { value = decodeURIComponent(value); } catch { /* keep the original path */ }
  const normalized = value
    .replace(/^[/\\]+(?=[A-Za-z]:)/, "")
    .replaceAll("\\", "/")
    .replace(/\/+/g, "/")
    .replace(/\/$/, "");
  // Windows module paths are case-insensitive; POSIX paths are not. Keeping
  // POSIX case prevents an unrelated transitive module from being treated as
  // this package's optional loader.
  return /^(?:[A-Za-z]:\/|\/\/)/.test(normalized) ? normalized.toLowerCase() : normalized;
}


function isCompanion(specifier: string, packageJson = false): boolean {
  if (!specifier.startsWith(companionStem)) return false;
  let suffix = specifier.slice(companionStem.length);
  if (packageJson && suffix.endsWith("/package.json")) suffix = suffix.slice(0, -"/package.json".length);
  return suffix.length > 0 && !suffix.includes("/");
}
